INSERT INTO public.personal_best_global (id_user,id_level,id_record,date_created,date_updated) SELECT $1,$2,$3,clock_timestamp(),clock_timestamp() WHERE NOT EXISTS(SELECT 1 FROM public.record r WHERE r.id_user=$1 AND r.id_level=$2 AND zc_private.record_is_eligible(r.id) AND (r.time<$4 OR (r.time=$4 AND r.id<$3))) ON CONFLICT (id_user,id_level) DO UPDATE SET id_record=excluded.id_record,date_updated=excluded.date_updated WHERE NOT zc_private.record_is_eligible(personal_best_global.id_record) OR (SELECT current_record.time FROM public.record current_record WHERE current_record.id=personal_best_global.id_record)>$4 RETURNING id
